#include <limits>
#include <iostream>

int main() {
    // Querying integer properties
    std::cout << "Max int: " << std::numeric_limits<int>::max() << "\n";

    // Querying floating-point properties
    std::cout << "Float Epsilon: " 
              << std::numeric_limits<float>::epsilon() << "\n";

    // Checking representation details
    if (std::numeric_limits<double>::is_iec559) {
        std::cout << "Double conforms to IEEE 754.\n";
    }
}
